// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/governance/retention-schedules", wrapper.GovListRetentionSchedules)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/governance/retention-schedules", wrapper.GovCreateRetentionSchedule)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/governance/retention-schedules/{id}", wrapper.GovGetRetentionSchedule)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/admin/v1/governance/retention-schedules/{id}", wrapper.GovSetRetentionScheduleStatus)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/governance/disposal-jobs", wrapper.GovListDisposalJobs)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/governance/disposal-jobs/{id}", wrapper.GovGetDisposalJob)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/governance/disposal-jobs/{id}/approve", wrapper.GovApproveDisposalJob)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/governance/disposal-jobs/{id}/start", wrapper.GovStartDisposalJob)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/governance/disposal-jobs/{id}/complete", wrapper.GovCompleteDisposalJob)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/governance/disposal-jobs/{id}/release-hold", wrapper.GovReleaseDisposalJobHold)
	})

	return r
}

