// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GovListDisposalJobs Disposal jobs (DPX-05) — created automatically by the daily due-date sweep, or manually inspected here
	// (GET /admin/v1/governance/disposal-jobs)
	GovListDisposalJobs(ctx context.Context, request GovListDisposalJobsRequestObject) (GovListDisposalJobsResponseObject, error)
	// GovGetDisposalJob One disposal job
	// (GET /admin/v1/governance/disposal-jobs/{id})
	GovGetDisposalJob(ctx context.Context, request GovGetDisposalJobRequestObject) (GovGetDisposalJobResponseObject, error)
	// GovApproveDisposalJob Approve a pending job (BP-11's confirm+approve step) — refused if the asset is under an active legal hold
	// (POST /admin/v1/governance/disposal-jobs/{id}/approve)
	GovApproveDisposalJob(ctx context.Context, request GovApproveDisposalJobRequestObject) (GovApproveDisposalJobResponseObject, error)
	// GovCompleteDisposalJob Close a disposal job — the acceptance criterion's gate, refused without an evidence file
	// (POST /admin/v1/governance/disposal-jobs/{id}/complete)
	GovCompleteDisposalJob(ctx context.Context, request GovCompleteDisposalJobRequestObject) (GovCompleteDisposalJobResponseObject, error)
	// GovReleaseDisposalJobHold Clear an on_hold job back to pending once its legal hold has been lifted
	// (POST /admin/v1/governance/disposal-jobs/{id}/release-hold)
	GovReleaseDisposalJobHold(ctx context.Context, request GovReleaseDisposalJobHoldRequestObject) (GovReleaseDisposalJobHoldResponseObject, error)
	// GovStartDisposalJob Move an approved job to in_progress (IT begins the actual disposal work)
	// (POST /admin/v1/governance/disposal-jobs/{id}/start)
	GovStartDisposalJob(ctx context.Context, request GovStartDisposalJobRequestObject) (GovStartDisposalJobResponseObject, error)
	// GovListRetentionSchedules Retention schedules (DPX-05) — one per asset's recurring disposal clock
	// (GET /admin/v1/governance/retention-schedules)
	GovListRetentionSchedules(ctx context.Context, request GovListRetentionSchedulesRequestObject) (GovListRetentionSchedulesResponseObject, error)
	// GovCreateRetentionSchedule Create a retention schedule against a RoPA retention rule and asset (FK-checked under RLS)
	// (POST /admin/v1/governance/retention-schedules)
	GovCreateRetentionSchedule(ctx context.Context, request GovCreateRetentionScheduleRequestObject) (GovCreateRetentionScheduleResponseObject, error)
	// GovGetRetentionSchedule One retention schedule
	// (GET /admin/v1/governance/retention-schedules/{id})
	GovGetRetentionSchedule(ctx context.Context, request GovGetRetentionScheduleRequestObject) (GovGetRetentionScheduleResponseObject, error)
	// GovSetRetentionScheduleStatus Pause / resume / retire a schedule — a paused or retired schedule is never picked up by the daily due-check
	// (PATCH /admin/v1/governance/retention-schedules/{id})
	GovSetRetentionScheduleStatus(ctx context.Context, request GovSetRetentionScheduleStatusRequestObject) (GovSetRetentionScheduleStatusResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

